// The desktop app's Electron fallback (lib/electron.nix): which checks are the
// nixpkgs runtime's, the pair an entry is about, whether an entry is active,
// and the generated file. Further down, the Electron record
// (ci/electron-runtime.json) and the words the status page and the release
// notes show.
//
// ci/electron-fallback.json: { "<pin>": { version, assets: { <system>: hash },
// nixpkgs: <rev> } }. An entry makes that channel's `auto` pick bundled while
// its pin version, both .deb hashes and flake.lock's nixpkgs revision are
// exactly the entry's; otherwise it's inert. It's part of the tested tree:
// generated by candidate.ts (apply/tree with a channel list) from the tree
// itself, never written at publish.
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { SYSTEMS } from "./util.ts";

export const FALLBACK_FILE = "ci/electron-fallback.json";
export const CHANNELS = ["t3code", "t3code-nightly"] as const;
export type Channel = (typeof CHANNELS)[number];

export interface Pair { version: string; assets: Record<string, string>; nixpkgs: string }
export type Entries = Partial<Record<Channel, Pair>>;

/** The checks of one channel, by role. `auto`: the apps whose Electron is
 * whatever auto picks (in the runtime list only on a system where auto
 * picks nixpkgs); `forced`: the forced-nixpkgs check; `bundled`: its
 * forced-bundled twin. Smokes take the app names' smoke names. */
export const ROLES: Record<Channel, { auto: string[]; forced: string; bundled: string; smokes: Record<string, string> }> = {
  t3code: {
    // t3code-free has no bundled twin: its failures are ordinary, or
    // provisional (it builds on t3code-unwrapped) and confirmed on bundled.
    auto: ["t3code-unwrapped", "t3code"],
    forced: "t3code-electron-nixpkgs",
    bundled: "t3code-electron-bundled",
    smokes: { t3code: "desktop-smoke", "t3code-electron-nixpkgs": "desktop-smoke-electron-nixpkgs", "t3code-electron-bundled": "desktop-smoke-electron-bundled" },
  },
  "t3code-nightly": {
    auto: ["t3code-unwrapped-nightly", "t3code-nightly"],
    forced: "t3code-nightly-electron-nixpkgs",
    bundled: "t3code-nightly-electron-bundled",
    smokes: {
      "t3code-nightly": "desktop-smoke-nightly",
      "t3code-nightly-electron-nixpkgs": "desktop-smoke-nightly-electron-nixpkgs",
      "t3code-nightly-electron-bundled": "desktop-smoke-nightly-electron-bundled",
    },
  },
};

/** A channel's runtime list on one system: the auto apps and their smoke
 * when auto picks nixpkgs there, and the forced check and its smoke unless
 * it's "not applicable". */
export function runtimeList(channel: Channel, autoIsNixpkgs: boolean, forcedApplicable: boolean): string[] {
  const r = ROLES[channel];
  const list: string[] = [];
  if (autoIsNixpkgs) list.push(...r.auto, ...r.auto.filter((a) => r.smokes[a]).map((a) => r.smokes[a]));
  if (forcedApplicable) list.push(r.forced, r.smokes[r.forced]);
  return list.sort();
}
export const bundledList = (channel: Channel) => [ROLES[channel].bundled, ROLES[channel].smokes[ROLES[channel].bundled]];

/** A tree's files by path (null when absent): a directory on disk, or a
 * candidate tree (candidate.ts). */
export type Reader = (path: string) => string | null;
export const fromDir = (dir: string): Reader => (path) => {
  const f = join(dir, path);
  return existsSync(f) ? readFileSync(f, "utf8") : null;
};
const at = (tree: string | Reader): Reader => (typeof tree === "string" ? fromDir(tree) : tree);

/** The pair a tree has for a channel (its pin and flake.lock), or null
 * without that pin. */
export function pairOf(tree: string | Reader, channel: Channel): Pair | null {
  const read = at(tree);
  const pinText = read(`versions/${channel}.json`);
  if (pinText === null) return null;
  const pin = JSON.parse(pinText);
  const lock = JSON.parse(read("flake.lock") ?? "{}");
  return {
    version: pin.version,
    assets: Object.fromEntries([...SYSTEMS].sort().map((s) => [s, pin.assets?.[s]?.hash ?? ""])),
    // No flake.lock (or an odd one): a revision no entry can have.
    nixpkgs: String(lock?.nodes?.nixpkgs?.locked?.rev ?? ""),
  };
}
export const samePair = (a: Pair | null | undefined, b: Pair | null | undefined) =>
  !!a && !!b && a.version === b.version && a.nixpkgs === b.nixpkgs && SYSTEMS.every((s) => a.assets[s] === b.assets[s]);

/** The schema (as lib/electron.nix checks it). */
export function valid(data: unknown): data is Entries {
  if (!data || typeof data !== "object" || Array.isArray(data) || !Object.keys(data).length) return false;
  const systems = [...SYSTEMS].sort();
  return Object.entries(data).every(([k, e]: [string, any]) =>
    (CHANNELS as readonly string[]).includes(k) && !!e && typeof e === "object"
    && JSON.stringify(Object.keys(e).sort()) === JSON.stringify(["assets", "nixpkgs", "version"])
    && typeof e.version === "string" && e.version !== ""
    && typeof e.nixpkgs === "string" && /^[0-9a-f]{40}$/.test(e.nixpkgs)
    && !!e.assets && typeof e.assets === "object"
    && JSON.stringify(Object.keys(e.assets).sort()) === JSON.stringify(systems)
    && systems.every((s) => typeof e.assets[s] === "string" && /^sha256-[A-Za-z0-9+/]{43}=$/.test(e.assets[s])));
}

/** A tree's entries ({} when absent or malformed). */
export function readEntries(tree: string | Reader): Entries {
  const text = at(tree)(FALLBACK_FILE);
  if (text === null) return {};
  try {
    const data = JSON.parse(text);
    return valid(data) ? data : {};
  } catch {
    return {};
  }
}

/** The channels with an active entry in a tree. */
export const activeChannels = (tree: string | Reader): Channel[] => {
  const entries = readEntries(tree);
  return CHANNELS.filter((c) => samePair(entries[c], pairOf(tree, c)));
};

/** Canonical form: sorted keys, two-space JSON, newline-terminated (what the
 * electron-fallback check compares with `jq -S --indent 2`). */
export function canonical(value: unknown): string {
  const sort = (v: any): any => (Array.isArray(v) ? v.map(sort) : v && typeof v === "object"
    ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, sort(v[k])])) : v);
  return `${JSON.stringify(sort(value), null, 2)}\n`;
}

/** The file a tree gets for a channel list: its still-active entries plus
 * the listed channels (their pairs from the tree), inert ones dropped; null
 * (no file) when nothing is left. Used only with a channel list: without
 * one, a tree's file stays exactly as it is. */
export function generated(tree: string | Reader, channels: Channel[]): string | null {
  const keep = activeChannels(tree);
  const entries: Entries = {};
  for (const c of CHANNELS) {
    if (!keep.includes(c) && !channels.includes(c)) continue;
    const pair = pairOf(tree, c);
    if (pair) entries[c] = pair;
  }
  return Object.keys(entries).length ? canonical(entries) : null;
}

/** generated(), written to a directory. */
export function generate(dir: string, channels: Channel[]): void {
  const text = generated(dir, channels);
  const f = join(dir, FALLBACK_FILE);
  if (text !== null) {
    mkdirSync(dirname(f), { recursive: true });
    writeFileSync(f, text);
  }
  else rmSync(f, { force: true });
}

export const parseChannels = (arg: string | undefined): Channel[] =>
  (arg ?? "").split(",").filter(Boolean).map((c) => {
    if (!(CHANNELS as readonly string[]).includes(c)) throw new Error(`not an Electron fallback channel: ${c}`);
    return c as Channel;
  });

// ci/electron-runtime.json: which Electron each Desktop app pin's `auto` picks
// on each system, without the fallback, from evaluating the package
// (scripts/ci/electron-runtime.ts). { "<pin>": { "<system>": { choice,
// version, bundled, rev } } }: `bundled` the pin's `electron` it was worked out
// for (bundledOf), `rev` flake.lock's nixpkgs revision. Best effort but never
// wrong: an entry counts only while both match its tree, and the
// electron-runtime check fails one that matches and disagrees with Nix.
export const RUNTIME_FILE = "ci/electron-runtime.json";
export interface Runtime { choice: "nixpkgs" | "bundled"; version: string | null; bundled: string | null; rev: string }
export type RuntimeRecord = Partial<Record<Channel, Record<string, Runtime>>>;
/** One evaluated (pin, system, bundled, rev): a row of the table that
 * electron-runtime.ts makes and candidate.ts writes records from. */
export interface Row extends Runtime { pin: Channel; system: string }

const SEMVER = /^\d+\.\d+\.\d+$/;
/** A pin's bundled Electron, as the record has it: its `electron` when a
 * plain X.Y.Z, otherwise null (lib/electron.nix's semver rule). */
export const bundledOf = (pin: any): string | null =>
  typeof pin?.electron === "string" && SEMVER.test(pin.electron) ? pin.electron : null;

/** One system's entry (as lib/electron.nix runtimeValid checks it): exactly
 * those keys; `bundled` X.Y.Z or null; `rev` 40 hex; nixpkgs with an X.Y.Z
 * version and a known bundled one, bundled with version = bundled. */
export function validRuntime(e: any): e is Runtime {
  if (!e || typeof e !== "object" || Array.isArray(e)) return false;
  if (JSON.stringify(Object.keys(e).sort()) !== JSON.stringify(["bundled", "choice", "rev", "version"])) return false;
  const semverOrNull = (v: unknown) => v === null || (typeof v === "string" && SEMVER.test(v));
  if (!semverOrNull(e.bundled) || !semverOrNull(e.version)) return false;
  if (typeof e.rev !== "string" || !/^[0-9a-f]{40}$/.test(e.rev)) return false;
  if (e.choice === "nixpkgs") return e.version !== null && e.bundled !== null;
  return e.choice === "bundled" && e.version === e.bundled;
}

/** The record's schema: a non-empty object of Desktop app pins, each with
 * exactly the flake's systems. */
export function validRecord(data: unknown): data is RuntimeRecord {
  if (!data || typeof data !== "object" || Array.isArray(data) || !Object.keys(data).length) return false;
  const systems = [...SYSTEMS].sort();
  return Object.entries(data).every(([k, e]: [string, any]) =>
    (CHANNELS as readonly string[]).includes(k) && !!e && typeof e === "object" && !Array.isArray(e)
    && JSON.stringify(Object.keys(e).sort()) === JSON.stringify(systems)
    && systems.every((s) => validRuntime(e[s])));
}

/** A tree's record ({} when absent or malformed). */
export function readRecord(tree: string | Reader): RuntimeRecord {
  const text = at(tree)(RUNTIME_FILE);
  if (text === null) return {};
  try {
    const data = JSON.parse(text);
    return validRecord(data) ? data : {};
  } catch {
    return {};
  }
}

export const pinOf = (read: Reader, channel: Channel): any => {
  const text = read(`versions/${channel}.json`);
  if (text === null) return null;
  try { return JSON.parse(text); } catch { return null; }
};
export const revOf = (read: Reader): string => {
  try { return String(JSON.parse(read("flake.lock") ?? "{}")?.nodes?.nixpkgs?.locked?.rev ?? ""); } catch { return ""; }
};

/** A channel's record entries that describe this tree (both systems'
 * `bundled` and `rev` are the tree's), or null. */
export function recordFor(tree: string | Reader, channel: Channel): Record<string, Runtime> | null {
  const read = at(tree);
  const pin = pinOf(read, channel);
  const e = readRecord(read)[channel];
  if (!pin || !e) return null;
  const bundled = bundledOf(pin), rev = revOf(read);
  return SYSTEMS.every((s) => e[s].bundled === bundled && e[s].rev === rev) ? e : null;
}

/** The table's rows that are well-formed (a row that isn't is ignored). */
export const validRows = (rows: unknown): Row[] => (Array.isArray(rows) ? rows : []).filter((r: any) => {
  if (!r || typeof r !== "object") return false;
  const { pin, system, ...rest } = r;
  return (CHANNELS as readonly string[]).includes(pin) && (SYSTEMS as readonly string[]).includes(system) && validRuntime(rest);
});

/** The record a tree gets (its text; null for no file; undefined to leave
 * the file as it is). A tree whose Desktop app pins and flake.lock are the
 * base's keeps the base's record byte for byte. Otherwise each pin the
 * table covers on every system gets fresh entries, and a pin it doesn't
 * keeps the base's (readers ignore them if they no longer match). A pure
 * function of the tree and the base, so every job writes the same bytes. */
export function runtimeRecord(read: Reader, base: Reader, rows: Row[]): string | null | undefined {
  const same = (path: string) => {
    const norm = (t: string | null) => { try { return t === null ? null : JSON.stringify(JSON.parse(t)); } catch { return t; } };
    return norm(read(path)) === norm(base(path));
  };
  if ([...CHANNELS.map((c) => `versions/${c}.json`), "flake.lock"].every(same)) return undefined;
  const old = readRecord(base), rev = revOf(read);
  const out: RuntimeRecord = {};
  for (const c of CHANNELS) {
    const pin = pinOf(read, c);
    if (!pin) continue;
    const bundled = bundledOf(pin);
    const found = SYSTEMS.map((s) => rows.find((r) => r.pin === c && r.system === s && r.bundled === bundled && r.rev === rev));
    if (found.every(Boolean)) {
      out[c] = Object.fromEntries(found.map((r) => [r!.system, { choice: r!.choice, version: r!.version, bundled: r!.bundled, rev: r!.rev }]));
    } else if (old[c]) out[c] = old[c];
  }
  return Object.keys(out).length ? canonical(out) : null;
}

/** What a tree says about a channel's Electron, for the status page and the
 * release notes (they build nothing): from the record when it describes the
 * tree, otherwise what git alone says. `bundled` is the pin's bundled
 * version, for the release notes' override sentence. Null without that pin. */
export function electronInfo(tree: string | Reader, channel: Channel): { words: string; bundled: string | null; recorded: boolean } | null {
  const read = at(tree);
  const text = read(`versions/${channel}.json`);
  if (text === null) return null;
  let pin: any;
  try { pin = JSON.parse(text); } catch { return null; }
  const bundled = bundledOf(pin);
  const fallback = activeChannels(read).includes(channel);
  const rec = recordFor(read, channel);
  if (rec) {
    const part = (e: Runtime) => {
      if (e.choice === "nixpkgs") return fallback ? `${e.bundled} (bundled; nixpkgs' ${e.version} failed this release's tests)` : `${e.version} (nixpkgs)`;
      return e.version === null ? "(bundled; version not recorded)" : `${e.version} (bundled)`;
    };
    const parts = SYSTEMS.map((s) => part(rec[s]));
    const words = parts.every((p) => p === parts[0])
      ? `Electron ${parts[0]}`
      : `Electron ${SYSTEMS.map((s, i) => `${parts[i]} on ${s}`).join(", ")}`;
    return { words, bundled, recorded: true };
  }
  if (bundled === null) return { words: "Electron: bundled (version not recorded)", bundled, recorded: false };
  if (fallback) return { words: `Electron: bundled ${bundled} (nixpkgs' failed this release's tests)`, bundled, recorded: false };
  return { words: `Electron: bundled ${bundled}; nixpkgs' newer patch of ${bundled.split(".")[0]} is used when available`, bundled, recorded: false };
}

/** electronInfo's words alone. */
export const electronNote = (tree: string | Reader, channel: Channel): string | null => electronInfo(tree, channel)?.words ?? null;
